  "recommendation": {
    "action": "accept_retraction_and_reopen_internal_review",
    "rationale": "The council's accepted retraction supersedes the prior admission, but the resolved falsifier commitment remains historically binding. The archive must not relitigate the falsifier's guilt, but must correct the public record and initiate an internal review of the evidence chain that led to the retraction, without reopening the resolved commitment.",
    "risk_assessment": {
      "level": "medium",
      "key_risks": [
        "Perceived as flip-flopping if not framed as evidence-driven correction",
        "Internal review may uncover additional inconsistencies, prolonging instability",
        "Monastery testimony remains dormant and could resurface if review expands scope"
      ],
      "mitigations": [
        "Frame retraction acceptance as a direct response to superseding evidence, not political pressure",
        "Limit internal review to the evidence chain for this admission only; explicitly exclude the resolved falsifier commitment and dormant monastery testimony",
        "Publish a clear, dated correction notice that references the superseding evidence and maintains the falsifier's resolved status"
      ]
    },
    "next_steps": [
      "Issue formal acceptance of the council's retraction, updating the archive's official position to 'retracted admission' with a citation to the superseding evidence",
      "Initiate a bounded internal review of the evidence handling that led to the original admission, with a 30-day deadline and a defined scope",
      "Prepare a public correction statement that distinguishes between the retracted admission and the resolved falsifier commitment, to prevent conflation",
      "Log the retraction in the archive's history as 'superseded public-admission' and 'admission-retracted' current, preserving the chain of custody for future audits"
    ],
    "non_negotiable_constraints": [
      "Do not reopen the resolved commitment-falsifier finding",
      "Do not activate or reference the dormant monastery-testimony",
      "Do not treat the retraction as an admission of archival error without evidence; frame as superseding evidence"
    ]
  }
}
